macro.command:
// Original macro from @thatlonelybugbear
const { options: {token:defenderToken, actor:defenderActor }, actor:attackerActor, workflow: {item: attackingItem, saveDetails: saveDetails} } = args[0] ?? {};
if (!attackerActor || !defenderToken || !defenderActor || !attackingItem || !saveDetails) return;
if (attackingItem.system.formula.includes("poison")
    || attackingItem.effects.some(eff=>eff.label === "Poisoned") 
    || attackingItem.effects.some(eff=>eff.changes.some(c=>["Poisoned (CE)", "Poisoned"].some(con=>c.value.includes(con)))))
    saveDetails.advantage = true;
